import{_ as i,l,o as e,c,v as t,p as s,x as r,d as T,i as n,S as p}from"./chunks/framework.InCnrqk-.js";const L=JSON.parse('{"title":"TTL 与 traceroute","description":"","frontmatter":{"title":"TTL 与 traceroute","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ttl-traceroute.md","filePath":"cs/ttl-traceroute.md","lastUpdated":1789023840000}'),d={name:"cs/ttl-traceroute.md"};function u(P,a,h,C,_,E){const o=l("Mermaid");return e(),c("div",null,[a[1]||(a[1]=t('<h1 id="ttl-与-traceroute" tabindex="-1">TTL 与 traceroute <a class="header-anchor" href="#ttl-与-traceroute" aria-label="Permalink to &quot;TTL 与 traceroute&quot;">​</a></h1><div class="epigraph"><p>TTL/Hop Limit 每跳减一，到零则丢并 ICMP；traceroute 故意让它在沿途逐跳过期，画出一条（可能不对称的）路径快照。</p><footer>—— 据 RFC 791 TTL；RFC 4443 ICMPv6；Van Jacobson traceroute 传统整理</footer></div><p>主干<a href="/cs/icmp">ICMP</a> 已有不可达类型。<a href="/cs/pmtud">上一课</a> 用 ICMP 传 MTU。缺口是<strong>用过期当探针</strong>：traceroute 的 TTL=1,2,… 与 ECMP 下的多路径假象。本课结束域内与域间课序。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>环路时 TTL 防止包永生，接住距离向量病的数据面版本。traceroute：UDP/ICMP/TCP 探针，听 Time Exceeded。ECMP：每次探针哈希不同，画出的「路径」是多条边的拼接，不是一次流的路。MPLS：可能看到 ICMP 来自中间，标签栈影响返回。防火墙丢探针或限速，图残缺。</p><p>不要把 traceroute 当控制面：它看不见 BGP 政策意图，只看见当时数据面。</p><p><span class="marginnote">Paris traceroute 用稳定五元组对付 ECMP。本课钉对象。反向路径不对称常见。</span></p><h3 id="图是快照" tabindex="-1">图是快照 <a class="header-anchor" href="#图是快照" aria-label="Permalink to &quot;图是快照&quot;">​</a></h3><p>TTL 防环并支撑探针。ECMP 会把多条边拼成假路径。过滤 ICMP 与 PMTUD 黑洞同源。看不见 BGP 意图。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：TTL 1 到第一跳，2 到第二跳。对照 ping：ping 固定 TTL 测可达与 RTT，不画图。卫星第一跳 RTT 就很大，图仍短。</p>',11)),(e(),s(p,null,{default:r(()=>[n(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20T1%5B%22TTL%3D1%22%5D%20--%3E%20H1%5B%22%E7%AC%AC%E4%B8%80%E8%B7%B3%20ICMP%22%5D%0A%20%20T2%5B%22TTL%3D2%22%5D%20--%3E%20H2%5B%22%E7%AC%AC%E4%BA%8C%E8%B7%B3%22%5D%0A%20%20HASH%5B%22%E6%8E%A2%E9%92%88%E5%93%88%E5%B8%8C%E5%8F%98%22%5D%20--%3E%20FAKE%5B%22ECMP%20%E6%8B%BC%E5%9B%BE%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[T(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>与 LLDP 对照：LLDP 一跳身份，traceroute 多跳 IP。与 BGP 收敛对照：路径在收敛中途会跳。RPKI 无效丢弃发生在边界，探针可能突然消失。VXLAN 外层 TTL 与内层独立，排障要看你 ping 的是哪一层。</p><p>安全：TTL 过期消息可泄露拓扑，有人过滤——于是与 PMTUD 黑洞同源。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 in-band OAM 的全部。路由器架构是下一课序第一课。后课默认：TTL 防环并支撑 traceroute；图是快照且受 ECMP 污染。</p><p>把 traceroute 当 SLA 监测不够：要固定流标识与数据面遥测。</p><p>上一课留下的缺口在本课收口；「TTL 与 traceroute」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/router-architecture">路由器架构</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>TTL 递减防环；零则 ICMP。</li><li>traceroute 是逐跳过期探测。</li><li>ECMP 与过滤使拓扑图不可直读。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 791；RFC 4443；Paris traceroute。</li></ul>',10))])}const f=i(d,[["render",u]]);export{L as __pageData,f as default};
